using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using SaucyMVC.Data; using SaucyMVC.Services;
namespace SaucyMVC.Controllers; public class StaffController:BaseController { readonly SaucyDbContext _db; readonly OrderWorkflowService _workflow; public StaffController(SaucyDbContext db,OrderWorkflowService workflow){_db=db;_workflow=workflow;} IActionResult Denied()=>RedirectToAction("Login","Account",new{role="Staff"}); bool OkStaff()=>IsRole("Staff","Admin");
 public async Task<IActionResult> Index(){if(!OkStaff())return Denied();var today=DateTime.Today;var tomorrow=today.AddDays(1);ViewBag.Confirmed=await _db.Orders.CountAsync(x=>x.Status=="Confirmed");ViewBag.Preparing=await _db.Orders.CountAsync(x=>x.Status=="Preparing");ViewBag.Ready=await _db.Orders.CountAsync(x=>x.Status=="Ready");ViewBag.CompletedToday=await _db.Orders.CountAsync(x=>x.Status=="Completed"&&x.OrderedAt>=today&&x.OrderedAt<tomorrow);return View();}
 public async Task<IActionResult> Orders(string? status){if(!OkStaff())return Denied();var activeStatuses=new[]{"Confirmed","Preparing","Ready"};var q=_db.Orders.Include(x=>x.User).Include(x=>x.Reservation).ThenInclude(r=>r!.DiningTable).Include(x=>x.Items).ThenInclude(i=>i.MenuItem).Include(x=>x.StatusHistory).AsSplitQuery().AsQueryable();ViewBag.Confirmed=await _db.Orders.CountAsync(x=>x.Status=="Confirmed");ViewBag.Preparing=await _db.Orders.CountAsync(x=>x.Status=="Preparing");ViewBag.Ready=await _db.Orders.CountAsync(x=>x.Status=="Ready");if(!string.IsNullOrWhiteSpace(status)&&activeStatuses.Contains(status))q=q.Where(x=>x.Status==status);else q=q.Where(x=>activeStatuses.Contains(x.Status));ViewBag.Status=status;ViewBag.OrderQueueVersion=await GetOrderQueueVersionAsync();return View(await q.OrderByDescending(x=>x.CancellationRequestStatus=="Pending").ThenBy(x=>x.OrderedAt).ToListAsync());}
 [HttpGet,ResponseCache(NoStore=true,Location=ResponseCacheLocation.None)] public async Task<IActionResult> OrderQueueVersion(){if(!OkStaff())return Unauthorized();return Json(new{version=await GetOrderQueueVersionAsync(),serverTime=DateTime.Now});}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> SetOrderStatus(int id,string status){if(!OkStaff())return Denied();var o=await _db.Orders.FindAsync(id);if(o==null){TempData["Error"]="That order could not be found.";return RedirectToAction(nameof(Orders));}if(o.CancellationRequestStatus=="Pending"){TempData["Error"]=$"Order #{o.Id} is waiting for an administrator's cancellation decision.";return RedirectToAction(nameof(Orders));}var nextStatus=OrderWorkflowService.GetStaffNextStatus(o.Status);if(status==nextStatus){_workflow.ChangeStatus(o,status,CurrentUserId,CurrentUserName,CurrentRole);await _db.SaveChangesAsync();TempData["Success"]=$"Order #{o.Id} is now {status.ToLowerInvariant()}.";}else TempData["Error"]="That status change is not part of the staff workflow. Ask an administrator to correct the order.";return RedirectToAction(nameof(Orders));}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> RequestCancellation(int id,string reason){if(!OkStaff())return Denied();var o=await _db.Orders.FindAsync(id);var activeStatuses=new[]{"Confirmed","Preparing","Ready"};if(o==null||!activeStatuses.Contains(o.Status)){TempData["Error"]="Only an active order can be reported for cancellation.";return RedirectToAction(nameof(Orders));}reason=(reason??"").Trim();if(reason.Length<5||reason.Length>500){TempData["Error"]="Explain the order problem in 5 to 500 characters.";return RedirectToAction(nameof(Orders));}if(o.CancellationRequestStatus=="Pending"){TempData["Error"]=$"Order #{o.Id} already has a cancellation request awaiting Admin.";return RedirectToAction(nameof(Orders));}o.CancellationRequestStatus="Pending";o.CancellationReason=reason;o.CancellationRequestedAt=DateTime.Now;o.CancellationRequestedByUserId=CurrentUserId;_workflow.RecordEvent(o,"Cancellation requested",CurrentUserId,CurrentUserName,CurrentRole,reason);await _db.SaveChangesAsync();TempData["Success"]=$"Order #{o.Id} was reported to Admin. Preparation is paused until a decision is made.";return RedirectToAction(nameof(Orders));}
 public async Task<IActionResult> History(){if(!OkStaff())return Denied();return View(await _db.Orders.Include(x=>x.User).Include(x=>x.Reservation).ThenInclude(r=>r!.DiningTable).Include(x=>x.Items).ThenInclude(i=>i.MenuItem).Include(x=>x.StatusHistory).AsSplitQuery().Where(x=>x.Status=="Completed"||x.Status=="Cancelled").OrderByDescending(x=>x.OrderedAt).ToListAsync());}
 async Task<string> GetOrderQueueVersionAsync(){var latestOrderId=await _db.Orders.MaxAsync(x=>(int?)x.Id)??0;var latestHistoryId=await _db.OrderStatusHistory.MaxAsync(x=>(int?)x.Id)??0;return $"{latestOrderId}:{latestHistoryId}";}
}
